// seed: tests/seed.admin.spec.ts (+ buyer для заказа в тесте @data)
// #26c50b (עבר QA 25.10; adbff48 + миграция 20261022100000): /dashboard?period=1 — график «הכנסות» по часам суток
// (0…текущий час, местное время Asia/Jerusalem), сумма точек = KPI «הכנסות»; оплата попадает в час, когда она записана,
// а не в час создания заказа. Выбор периода / «לעומת אתמול» / 7-30-90 — уже в dashboard-period-url.spec.ts, здесь не повторяется.
// Данные берутся из ответа rpc/dashboard_metrics (p_days=1): поля ряда распознаются по названию (hour/bucket/date… и revenue/amount/value…);
// если форма ответа другая — тест падает с сообщением «форма ответа не распознана» (это ошибка теста, а не продукта).
// Тест @data: свой товар QA-AUTO-26c5-<ts> (₪1), заказ buyer «QA-AUTO-26c5-<ts>» (создан раньше в beforeAll), утверждение,
// оплата ₪1 (= весь заказ) → доводится до «סופקה» (утверждённый заказ не отклоняется), товар удаляется.
import { test, expect, Page, Response } from '@playwright/test';
import { auth, createStockedProduct, buyerPlaceOrder, openOrder, header, deleteProduct } from '../orders/_qa-order';

test.use({ storageState: auth('admin') });

const TZ = 'Asia/Jerusalem';
const hourNow = () => Number(new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', hourCycle: 'h23' }).format(new Date()));
const LABEL_KEYS = ['hour', 'bucket', 'ts', 'time', 'period', 'date', 'day', 'label', 'x'];
const VALUE_KEYS = ['revenue', 'amount', 'value', 'total', 'sum', 'income', 'y'];
type Point = { hour: number; value: number };
type Metrics = Record<string, unknown>;

/** Час точки по метке: число 0–23, «HH:00», или дата-время → час в Asia/Jerusalem. */
function hourOf(label: unknown): number | null {
  if (typeof label === 'number' && label >= 0 && label <= 23) return label;
  const s = String(label);
  if (/^\d{1,2}$/.test(s)) return Number(s);
  const hm = s.match(/^(\d{1,2}):\d{2}$/);
  if (hm) return Number(hm[1]);
  const d = new Date(s);
  if (/\d{4}-\d{2}-\d{2}[T ]\d{2}/.test(s) && !Number.isNaN(d.getTime()))
    return Number(new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', hourCycle: 'h23' }).format(d));
  return null;
}

/** Почасовой ряд «сегодня» из ответа dashboard_metrics. */
function hourlySeries(m: Metrics): Point[] {
  const arrays = Object.entries(m).filter(([, v]) => Array.isArray(v) && (v as unknown[]).length && typeof (v as unknown[])[0] === 'object') as [string, Record<string, unknown>[]][];
  const preferred = arrays.find(([k]) => k === 'series') ?? arrays.find(([k]) => /series|chart|hour|timeline/i.test(k)) ?? arrays[0];
  if (!preferred) throw new Error(`форма ответа не распознана: нет массива точек (${Object.keys(m).join(', ')})`);
  const items = preferred[1];
  const keys = Object.keys(items[0]);
  const lk = LABEL_KEYS.find((k) => keys.includes(k));
  const vk = VALUE_KEYS.find((k) => keys.includes(k));
  if (!lk || !vk) throw new Error(`форма ответа не распознана: ${preferred[0]}[0] = ${JSON.stringify(items[0])}`);
  return items.map((it) => {
    const h = hourOf(it[lk]);
    if (h === null) throw new Error(`форма ответа не распознана: метка «${String(it[lk])}» — не час`);
    return { hour: h, value: Number(it[vk]) || 0 };
  });
}

const revenueOf = (m: Metrics) => Number(m.revenue);
const sum = (pts: Point[]) => Math.round(pts.reduce((a, p) => a + p.value, 0) * 100) / 100;
const at = (pts: Point[], h: number) => pts.filter((p) => p.hour === h).reduce((a, p) => a + p.value, 0);

async function loadToday(page: Page): Promise<{ m: Metrics; hBefore: number; hAfter: number }> {
  const isToday = (r: Response) => r.url().includes('/rpc/dashboard_metrics') && /"p_days":\s*1\b/.test(r.request().postData() ?? '');
  const hBefore = hourNow();
  const [res] = await Promise.all([page.waitForResponse(isToday, { timeout: 30_000 }), page.goto('/dashboard?period=1')]);
  const hAfter = hourNow();
  await expect(page.getByRole('heading', { level: 1, name: 'לוח בקרה' })).toBeVisible({ timeout: 30_000 });
  return { m: (await res.json()) as Metrics, hBefore, hAfter };
}

test.describe('ui-general — לוח בקרה «היום» לפי שעות (#26c50b)', () => {
  test('«היום»: ציר שעות 00:00…השעה הנוכחית (שעון ישראל), סכום הנקודות = «הכנסות» #26c50b @desktop @prod-safe', async ({ page }) => {
    const { m, hBefore, hAfter } = await loadToday(page);
    const pts = hourlySeries(m);
    const hours = [...new Set(pts.map((p) => p.hour))].sort((a, b) => a - b);
    expect(hours[0], 'ряд начинается с 00:00').toBe(0);
    expect([hBefore, hAfter], `последний час ряда (${hours.at(-1)}) = текущий час ${TZ}`).toContain(hours.at(-1));
    expect(sum(pts), 'сумма точек = revenue').toBeCloseTo(revenueOf(m), 2);

    // в интерфейсе: график «הכנסות היום…», подписи оси — часы, первая 00:00; карточка «הכנסות» = revenue
    const chart = page.getByRole('img', { name: /^הכנסות היום/ });
    await expect(chart).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(/^00:00$/).first()).toBeVisible();
    const card = (await page.getByText('הכנסות', { exact: true }).first().locator('../..').innerText()).replace(/\s+/g, ' ');
    const shown = Number((card.match(/₪([\d,]+(?:\.\d+)?)/) ?? ['', 'NaN'])[1].replace(/,/g, ''));
    expect(Math.abs(shown - revenueOf(m)), `карточка «הכנסות» ${card}`).toBeLessThan(1);
  });

  test.describe('תשלום נרשם בשעה שבה התקבל (QA-AUTO)', () => {
    test.describe.configure({ mode: 'serial' });
    const TS = Date.now().toString().slice(-7);
    const P = `QA-AUTO-26c5-${TS}`;
    const st: { no?: string; createdHour?: number; product?: boolean } = {};

    test.beforeAll(async ({ browser }) => {
      test.setTimeout(240_000);
      const ctx = await browser.newContext({ storageState: auth('admin'), baseURL: test.info().project.use.baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
      const page = await ctx.newPage();
      try {
        st.product = true;
        const id = await createStockedProduct(page, P, `QA26C5${TS}`, 1, 1);
        st.createdHour = hourNow();
        st.no = await buyerPlaceOrder(browser, [{ id, name: P, qty: 1 }], P);
        await openOrder(page, st.no);
        await page.getByRole('button', { name: 'אישור הזמנה' }).click();
        const dlg = page.getByRole('dialog');
        await dlg.getByRole('textbox', { name: 'הערה (לא חובה)' }).fill(`${P} approve`);
        await dlg.getByRole('button', { name: 'אשר הזמנה' }).click();
        await expect(header(page)).toContainText('אושרה', { timeout: 20_000 });
      } finally {
        await ctx.close();
      }
    });

    test.afterAll(async ({ browser }) => {
      test.setTimeout(180_000);
      const ctx = await browser.newContext({ storageState: auth('admin'), baseURL: test.info().project.use.baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
      const page = await ctx.newPage();
      try {
        if (st.no) {
          await openOrder(page, st.no);
          // утверждённый заказ не отклоняется — доводим до «סופקה»
          for (const b of ['סמן כמוכנה למשלוח', 'סמן כיצאה למשלוח', 'סמן כסופקה']) {
            const btn = page.getByRole('button', { name: b });
            if ((await btn.count()) && (await btn.isEnabled())) { await btn.click(); await expect(btn).toHaveCount(0, { timeout: 20_000 }); }
          }
        }
        if (st.product) await deleteProduct(page, P);
      } catch (e) {
        test.info().annotations.push({ type: 'cleanup', description: (e as Error).message.split('\n')[0] });
      } finally {
        await ctx.close();
      }
    });

    test('תשלום ₪1 על הזמנה שנוצרה קודם — בשעה הנוכחית, לא בשעת יצירת ההזמנה; «הכנסות» +₪1 #26c50b @desktop @data', async ({ page }) => {
      test.setTimeout(180_000);
      test.skip(!st.no, 'заказ не создан');
      const before = await loadToday(page);
      const ptsBefore = hourlySeries(before.m);

      await openOrder(page, st.no!);
      const box = page.getByRole('heading', { name: 'סטטוס תשלום' }).locator('../..');
      await box.getByRole('button', { name: 'עדכון' }).click();
      await box.getByRole('combobox', { name: 'סטטוס תשלום' }).selectOption({ label: 'שולם חלקית' });
      await box.getByRole('textbox', { name: 'סכום שהתקבל כעת' }).fill('1');
      const payHour = hourNow();
      await box.getByRole('button', { name: 'שמירה' }).click();
      await expect(box).toContainText('₪1.00 מתוך ₪1.00', { timeout: 20_000 });

      const after = await loadToday(page);
      const ptsAfter = hourlySeries(after.m);
      expect(revenueOf(after.m) - revenueOf(before.m), '«הכנסות» за сегодня +₪1').toBeCloseTo(1, 2);
      expect(sum(ptsAfter), 'сумма точек = revenue').toBeCloseTo(revenueOf(after.m), 2);
      expect(at(ptsAfter, payHour) - at(ptsBefore, payHour), `оплата в часе ${payHour}:00 (часе оплаты)`).toBeCloseTo(1, 2);
      if (st.createdHour !== payHour) {
        expect(at(ptsAfter, st.createdHour!) - at(ptsBefore, st.createdHour!), `час создания ${st.createdHour}:00 не изменился`).toBeCloseTo(0, 2);
      } else {
        test.info().annotations.push({ type: 'note', description: `заказ создан и оплачен в одном часе (${payHour}:00) — отличие «час оплаты ≠ час создания» не проверено в этом прогоне` });
      }
    });
  });
});
